import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Toast Notification","description":"","frontmatter":{"prev":{"text":"Page Loading","link":"/documentation/field-types/others/page-loading"},"next":{"text":"Fetch Header Value Data","link":"/documentation/field-types/scraper-data/fetch-header-value-data"}},"headers":[],"relativePath":"documentation/field-types/others/toast-notification.md","filePath":"documentation/field-types/others/toast-notification.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/others/toast-notification.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="toast-notification" tabindex="-1">Toast Notification <a class="header-anchor" href="#toast-notification" aria-label="Permalink to “Toast Notification”">​</a></h1><p>Display customizable floating toast messages, banners, and milestone alerts on the web page during automated execution.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The <strong>Toast Notification</strong> field type renders non-intrusive on-screen visual banners directly inside the active browser tab. It helps operators and QA testers track real-time automation milestones, observe dynamic variables, and view debugging feedback as forms are populated.</p><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Toast Message Content</strong></td><td>Text Input</td><td>Message to display (set via Default Value or Excel column).</td><td>Yes</td></tr><tr><td><strong>Notification Gravity</strong></td><td>Dropdown</td><td>Vertical screen positioning (<code>top</code>, <code>bottom</code>).</td><td>Yes</td></tr><tr><td><strong>Notification Position</strong></td><td>Dropdown</td><td>Horizontal alignment (<code>left</code>, <code>center</code>, <code>right</code>).</td><td>Yes</td></tr><tr><td><strong>Notification Types</strong></td><td>Dropdown</td><td>Semantic alert theme (<code>info</code>, <code>success</code>, <code>warning</code>, <code>error</code>).</td><td>Yes</td></tr><tr><td><strong>Duration</strong></td><td>Number Input</td><td>Display duration in milliseconds (e.g., <code>3000</code> for 3 seconds).</td><td>Yes</td></tr></tbody></table><hr><h2 id="positioning" tabindex="-1">Positioning &amp; Styling Options <a class="header-anchor" href="#positioning" aria-label="Permalink to “Positioning &amp; Styling Options”">​</a></h2><h3 id="notification-gravity-vertical" tabindex="-1">Notification Gravity (Vertical) <a class="header-anchor" href="#notification-gravity-vertical" aria-label="Permalink to “Notification Gravity (Vertical)”">​</a></h3><ul><li><strong><code>top</code></strong>: Displays toast anchored at the top of the browser viewport.</li><li><strong><code>bottom</code></strong>: Displays toast anchored along the bottom screen edge.</li></ul><h3 id="notification-position-horizontal" tabindex="-1">Notification Position (Horizontal) <a class="header-anchor" href="#notification-position-horizontal" aria-label="Permalink to “Notification Position (Horizontal)”">​</a></h3><ul><li><strong><code>left</code></strong>: Aligns toast to the left.</li><li><strong><code>center</code></strong>: Centers toast horizontally across the screen.</li><li><strong><code>right</code></strong>: Aligns toast to the right edge (standard notification placement).</li></ul><h3 id="notification-semantic-types" tabindex="-1">Notification Semantic Types <a class="header-anchor" href="#notification-semantic-types" aria-label="Permalink to “Notification Semantic Types”">​</a></h3><ul><li><strong><code>info</code></strong>: Clean informational blue banner.</li><li><strong><code>success</code></strong>: Vibrant green confirmation banner.</li><li><strong><code>warning</code></strong>: Yellow/amber caution banner.</li><li><strong><code>error</code></strong>: Bold red alert banner.</li></ul><hr><h2 id="message-content" tabindex="-1">Message Templating <a class="header-anchor" href="#message-content" aria-label="Permalink to “Message Templating”">​</a></h2><p>You can define toast message content statically or dynamically:</p><h3 id="dynamic-spreadsheet-row-variables" tabindex="-1">Dynamic Spreadsheet Row Variables <a class="header-anchor" href="#dynamic-spreadsheet-row-variables" aria-label="Permalink to “Dynamic Spreadsheet Row Variables”">​</a></h3><p>Inject values from the active <code>.xlsx</code> record using <code>{$ColumnName$}</code>:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Processing customer: {$CustomerName$} (Account: {$AccountID$})</span></span></code></pre></div><h3 id="predefined-system-variables" tabindex="-1">Predefined System Variables <a class="header-anchor" href="#predefined-system-variables" aria-label="Permalink to “Predefined System Variables”">​</a></h3><p>Incorporate time stamps, random tokens, or row indexes:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Row #{$EDF_ROW_INDEX$} completed successfully at {$DATETIME_NOW$}</span></span></code></pre></div><hr><h2 id="examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Practical Examples”">​</a></h2><h3 id="example-1-submission-confirmation-toast" tabindex="-1">Example 1: Submission Confirmation Toast <a class="header-anchor" href="#example-1-submission-confirmation-toast" aria-label="Permalink to “Example 1: Submission Confirmation Toast”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Message: Form successfully submitted for {$FullName$}!</span></span>
<span class="line"><span>Notification Gravity: top</span></span>
<span class="line"><span>Notification Position: right</span></span>
<span class="line"><span>Notification Types: success</span></span>
<span class="line"><span>Duration: 3500</span></span></code></pre></div><h3 id="example-2-milestone-debug-warning" tabindex="-1">Example 2: Milestone Debug Warning <a class="header-anchor" href="#example-2-milestone-debug-warning" aria-label="Permalink to “Example 2: Milestone Debug Warning”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Message: Captcha encountered. Solving via 2Captcha...</span></span>
<span class="line"><span>Notification Gravity: bottom</span></span>
<span class="line"><span>Notification Position: center</span></span>
<span class="line"><span>Notification Types: warning</span></span>
<span class="line"><span>Duration: 5000</span></span></code></pre></div><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ul><li><strong>Keep Messages Concise</strong>: Short single-line alerts ensure optimal readability without blocking page interactions.</li><li><strong>Set Appropriate Durations</strong>: 3000–4000 milliseconds is ideal for operators to read notices without visual clutter.</li><li><strong>Choose Non-Blocking Corners</strong>: Use <code>top-right</code> or <code>bottom-right</code> to avoid obscuring central form buttons.</li></ul><hr><h2 id="related" tabindex="-1">Related Documentation <a class="header-anchor" href="#related" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field.html">Form Fields Overview</a></li><li><img src="/svg/code.svg" class="doc-icon"> <a href="/documentation/variable.html">Variables Reference</a></li><li><img src="/svg/beaker.svg" class="doc-icon"> <a href="/documentation/logs.html">Execution Logs</a></li></ul>`,37)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};